# Now let's look at the SHORT runs too - the typical range for "normal" 
python3 - <<'PY'
import json, os, glob

runs = []
for timing_path in glob.glob("larch-logs/implement/*/timing-report.json"):
    run_id = timing_path.split("/")[2]
    try:
        data = json.load(open(timing_path))
        for step in data.get("per_step", []):
            if "Step 5" in step.get("step", ""):
                pfile = f"larch-logs/implement/{run_id}/parent-issue.md"
                issue = "?"
                if os.path.exists(pfile):
                    content = open(pfile).read()
                    for line in content.split("\n"):
                        if "ISSUE_NUMBER=" in line:
                            issue = line.split("=")[1].strip()
                total = sum(s["duration_seconds"] for s in data.get("per_step", []))
                runs.append({
                    "id": run_id,
                    "issue": issue,
                    "step5": step["duration_seconds"],
                    "step5_hms": step["duration_hms"],
                    "total": total
                })
    except:
        pass

# Show distribution
print("Step 5 duration distribution:")
buckets = {"<30m": 0, "30-60m": 0, "1-2h": 0, "2-3h": 0, ">3h": 0}
for r in runs:
    s = r["step5"]
    if s < 1800: buckets["<30m"] += 1
    elif s < 3600: buckets["30-60m"] += 1
    elif s < 7200: buckets["1-2h"] += 1
    elif s < 10800: buckets["2-3h"] += 1
    else: buckets[">3h"] += 1
for k, v in buckets.items():
    print(f"  {k}: {v} runs")

# Sort by issue number (roughly chronological)
print("\nRecent runs by issue# (most recent 20):")
try:
    recent = sorted([r for r in runs if r["issue"] != "?"], key=lambda x: int(x["issue"]))[-20:]
    for r in recent:
        print(f"  #{r['issue']:>5}  step5={r['step5_hms']}  total={r['total']//60}m")
except:
    pass
PY
